const preguntaOriginal = $json.message?.text || $json.pregunta || "";

const normalizada = preguntaOriginal
  .toLowerCase()
  .normalize("NFD")
  .replace(/[\u0300-\u036f]/g, "")
  .trim();

return [
  {
    json: {
      pregunta_original: preguntaOriginal,
      pregunta_normalizada: normalizada,
      chat_id: $json.message?.chat?.id,
      canal: "telegram"
    }
  }
];

const p = $json.pregunta_normalizada;

let intencion = "desconocido";
let respuesta_directa = null;

if (
  p.includes("que es el ccd") ||
  p.includes("centro de competencias digitales")
) {
  intencion = "faq_directa";
  respuesta_directa = "El Centro de Competencias Digitales, CCD, es una iniciativa institucional orientada al fortalecimiento de habilidades digitales en la comunidad universitaria, mediante cursos sobre cultura digital, analítica, contenido digital y tecnologías transformativas.";
}
else if (
  p.includes("ruta de competencias digitales") ||
  p.includes("competencias digitales")
) {
  intencion = "faq_directa";
  respuesta_directa = "La Ruta de Competencias Digitales está organizada en tres pilares: Competencias Digitales Básicas, Analítica y Contenido Digital, y Tecnologías Transformativas.";
}
else if (
  p.includes("cuantos cursos") ||
  p.includes("cuantos debo tomar") ||
  p.includes("que cursos debo tomar")
) {
  intencion = "faq_directa";
  respuesta_directa = "La ruta contempla un curso obligatorio de competencias digitales básicas y cursos complementarios en Analítica y Contenido Digital y Tecnologías Transformativas.";
}
else if (
  p.includes("insignia") ||
  p.includes("certificacion") ||
  p.includes("certificado")
) {
  intencion = "rag_documentos";
}
else if (
  p.includes("cuando") ||
  p.includes("fecha") ||
  p.includes("inscripcion") ||
  p.includes("prueba diagnostica") ||
  p.includes("inicio de cursos")
) {
  intencion = "calendario";
}
else if (
  p.includes("he tomado") ||
  p.includes("mis cursos") ||
  p.includes("historial") ||
  p.includes("cursos realizados")
) {
  intencion = "cursos_estudiante";
}
else if (
  p.includes("noticias") ||
  p.includes("convocatorias") ||
  p.includes("nuevos cursos") ||
  p.includes("novedades")
) {
  intencion = "noticias";
}
else if (
  p.includes("analitica") ||
  p.includes("contenido digital") ||
  p.includes("tecnologias transformativas") ||
  p.includes("ia generativa")
) {
  intencion = "oferta_cursos";
}
else if (
  p.includes("hola") ||
  p.includes("buenas") ||
  p.includes("buenos dias") ||
  p.includes("buenas tardes")
) {
  intencion = "saludo";
  respuesta_directa = "Hola, soy el asistente del Centro de Competencias Digitales. Puedes preguntarme sobre cursos, calendario, ruta de competencias digitales, noticias o tu historial académico.";
}

return [
  {
    json: {
      ...$json,
      intencion,
      respuesta_directa
    }
  }
];

const base = $('Code - Detectar FAQ e intencion').first().json;
const eventos = $input.all().map((e) => e.json).filter((e) => e.evento);

let respuesta;

if (eventos.length === 0) {
  respuesta = "No hay eventos registrados en el calendario del CCD.";
} else {
  respuesta = "Eventos próximos del CCD:\n\n" + eventos.map((e) =>
    `• ${e.evento} (${e.fecha_inicio || "sin fecha"})`
  ).join("\n");
}

return [{ json: { ...base, respuesta } }];

const base = $('Code - Detectar FAQ e intencion').first().json;
const cursos = $input.all().map((i) => i.json).filter((c) => c.nombre);

let respuesta = "Oferta de cursos CCD:\n\n";

cursos.forEach((c) => {
  respuesta += `• ${c.nombre} (${c.categoria})\n`;
});

if (cursos.length === 0) {
  respuesta = "No hay cursos activos registrados en este momento.";
}

return [{ json: { ...base, respuesta } }];

const base = $input.first().json;
const p = base.pregunta_normalizada || '';

const codigoUnab = p.match(/\bu\d{8}\b/i);
const idNumerico = p.match(/\b\d{8}\b/);

return [{
  json: {
    ...base,
    codigo_unab: codigoUnab ? codigoUnab[0].toUpperCase() : null,
    id_estudiante: idNumerico ? idNumerico[0] : null,
    tiene_codigo: !!codigoUnab || !!idNumerico
  }
}];

const base = $input.first().json;

return [{
  json: {
    ...base,
    respuesta: "Para consultar tus cursos realizados necesito tu código UNAB o tu ID de estudiante. Ejemplo: U00175325 o 20240005."
  }
}];

const base = $('Code - Verificar codigo estudiante').first().json;
const cursos = $input.all().map((i) => i.json).filter((c) => c.nombre_materia);

let respuesta;

if (cursos.length === 0) {
  respuesta = "No se encontraron cursos registrados para el código indicado.";
} else {
  const estudiante = cursos[0];

  respuesta =
    `Cursos CCD registrados para ${estudiante.nombre_completo}\n` +
    `Programa: ${estudiante.programa_academico}\n` +
    `Código UNAB: ${estudiante.codigo_unab}\n` +
    `ID estudiante: ${estudiante.id_estudiante}\n\n` +
    cursos.map((c) =>
      `• ${c.nombre_materia} (${c.semestre})`
    ).join("\n");
}

return [{ json: { ...base, respuesta } }];

const base = $('Code - Detectar FAQ e intencion').first().json;
const noticias = $input.all().map((n) => n.json).filter((n) => n.titulo);

let respuesta;

if (noticias.length === 0) {
  respuesta = "No hay noticias disponibles en este momento.";
} else {
  respuesta = "Últimas noticias del CCD:\n\n" + noticias.map((n) =>
    `• ${n.titulo}`
  ).join("\n");
}

return [{ json: { ...base, respuesta } }];
